insert into public.pedagogical_content (id, question, objectif, tip, explication, accroche, a_observer, a_retenir, erreur_frequente, actions, dimension, niveau, tags_theme, tags_filtre, vote_vrai, vote_faux, source, is_public) values
('directrice-marees', 'Qu’est-ce que la marée change autour de nous ?', 'Relier un changement visible du rivage à la séance et aux milieux de vie.', 'Un changement de niveau ou un retour au même endroit suffit pour ouvrir le sujet. Partez de ce que le groupe constate.', 'Avec la marée, le rivage change de place : des zones sont découvertes puis recouvertes. Cela modifie nos accès et nos déplacements, mais aussi les moments où des animaux peuvent se nourrir ou rester à l’abri. Les horaires et les hauteurs prévues permettent d’anticiper ces changements sur notre site.', 'Tout à l’heure, la mer était là. Qu’est-ce que son déplacement a changé pour nous… et pour ce qui vit ici ?', 'Un repère sur le rivage, une zone découverte, un passage ou des oiseaux qui se nourrissent sur l’estran.', 'La marée fait évoluer à la fois notre terrain de pratique et les conditions de vie sur le littoral.', 'Le bord de mer serait un terrain fixe que l’on retrouve identique à chaque séance.', '[{"id":"directrice-marees-repere","label":"Retrouver le rivage","consigne":"À une pause, choisissez un repère fixe avec le groupe. Comparez la place de la mer à celle du début de séance. Faites nommer un changement pour notre activité et un changement pour le vivant.","confirmation":"Nous avons relié un changement de marée à notre séance ou au vivant."}]'::jsonb, 'COMPRENDRE', 1, array['caracteristiques_littoral','reperes_spatio_temporels']::text[], array['marée','estran','coefficient','mer','rivage']::text[], 'La marée transforme aussi les conditions de vie sur les zones qu’elle couvre et découvre.', 'La marée change seulement la hauteur d’eau, sans conséquence pour les animaux du rivage.', 'copun', true),
('directrice-courants', 'Où va l’eau qui nous entoure ?', 'Faire observer un mouvement de l’eau et relier transport, navigation et milieu.', 'Le sujet se glisse lors d’une dérive constatée ou d’une observation depuis le bord. Ne jetez rien à l’eau pour faire une démonstration.', 'Un courant déplace de l’eau : il peut entraîner un bateau, des algues ou des débris, et transporter de la nourriture pour le vivant. Sa direction et sa force dépendent de la marée et de la configuration du lieu, mais aussi du vent et d’autres mouvements de la mer. Une surface calme ne signifie donc pas une eau immobile.', 'Ce bout d’algue se déplace alors qu’il n’a ni voile ni moteur : où l’eau l’emmène-t-elle ?', 'Le déplacement d’écume ou d’algues déjà présentes, comparé à un repère fixe.', 'L’eau transporte : comprendre son mouvement aide à naviguer et à lire ce qui circule dans le milieu.', 'Quand il n’y a pas de vagues, l’eau ne bouge pas.', '[{"id":"directrice-courants-suivre","label":"Suivre un déplacement","consigne":"Lors d’une pause adaptée, faites suivre un élément naturellement présent à la surface par rapport à un repère fixe. Demandez ce que ce même mouvement pourrait transporter et ce qu’il change pour notre trajet.","confirmation":"Nous avons observé un déplacement de l’eau et parlé de ce qu’il transporte."}]'::jsonb, 'OBSERVER', 1, array['interactions_climatiques']::text[], array['courant','courants','dérive','eau','transport']::text[], 'Même une eau qui paraît calme peut transporter des éléments avec un courant.', 'Sans vagues, un bateau ne peut pas être entraîné par un courant.', 'copun', true),
('directrice-vagues', 'D’où viennent les vagues que l’on voit aujourd’hui ?', 'Utiliser les vagues de la séance pour relier le vent, la mer et le rivage.', 'Une attente avant la mise à l’eau ou une observation au retour permet d’en parler sans interrompre la pratique.', 'Le vent transmet de l’énergie à la surface de l’eau. Les vagues peuvent être formées sur place ou arriver d’une zone où le vent a soufflé auparavant : c’est la houle. En approchant du rivage, leur forme évolue avec la profondeur et le relief du fond. Elles participent aussi au déplacement du sable et des éléments déposés sur la plage.', 'Le vent est faible ici, mais il reste des vagues : où ont-elles pu commencer leur voyage ?', 'La direction d’arrivée, l’espacement des vagues et la façon dont elles changent près du bord.', 'Les vagues relient le vent, parfois lointain, au rivage qu’elles transforment.', 'Toutes les vagues visibles sont produites par le vent qui souffle ici et maintenant.', '[{"id":"directrice-vagues-comparer","label":"Du large au bord","consigne":"Depuis un point où l’observation est possible, faites suivre une vague vers le rivage. Demandez ce qui change dans sa forme, puis ce qu’elle peut déplacer sur la plage. Appuyez l’explication sur ce que le groupe vient de voir.","confirmation":"Nous avons relié les vagues observées à leur origine ou à un effet sur le rivage."}]'::jsonb, 'COMPRENDRE', 1, array['interactions_climatiques']::text[], array['vague','vagues','houle','mer','sable']::text[], 'Une houle peut arriver d’une zone où le vent a soufflé loin de notre plage.', 'S’il n’y a pas de vent sur notre plage, il ne peut pas y avoir de vagues.', 'copun', true),
('directrice-vent-ciel', 'Qu’est-ce que le ciel et le vent nous racontent aujourd’hui ?', 'Transformer les indices déjà utilisés en navigation en occasion d’observer et de raconter le milieu.', 'Partez d’un indice qui a déjà compté pour la séance : une rafale, des rides sur l’eau ou un changement de ciel. Un seul suffit.', 'Nos indices de navigation renseignent aussi sur le milieu : le vent agit sur la surface de l’eau et transporte de l’air, tandis que les nuages donnent des signes de l’évolution de l’atmosphère. Leur lecture gagne à combiner plusieurs observations et les prévisions. Un signe isolé ne permet pas d’expliquer tout le temps qu’il fait.', 'Ce signe nous aide à conduire la séance. Qu’est-ce qu’il nous apprend aussi sur ce qui se passe autour de nous ?', 'Un indice choisi avec le groupe : rides sur l’eau, nuage, déplacement d’une ombre ou différence d’exposition au vent.', 'Les indices utiles à notre pratique sont aussi des portes d’entrée pour comprendre notre milieu.', 'Un seul nuage ou une seule rafale suffirait à expliquer l’évolution des conditions.', '[{"id":"directrice-vent-ciel-indice","label":"Revenir sur un indice","consigne":"À une pause, faites choisir un signe visible et décrire ce qu’il montre. Revenez sur ce même signe plus tard : qu’est-ce qui a changé ? Reliez le constat aux décisions prises pendant la séance.","confirmation":"Nous avons utilisé un indice du ciel ou du vent pour parler de notre milieu."}]'::jsonb, 'OBSERVER', 1, array['interactions_climatiques']::text[], array['vent','ciel','nuage','nuages','météo','rafale']::text[], 'Comparer plusieurs indices et les prévisions aide à comprendre l’évolution des conditions.', 'Une seule rafale suffit à savoir comment le vent évoluera pendant toute la séance.', 'copun', true),
('directrice-plage-dunes', 'Pourquoi cette plage ne reste-t-elle pas toujours la même ?', 'Faire comprendre le déplacement du sable et l’intérêt de respecter les dunes à partir du trajet de la séance.', 'Le chemin vers la mise à l’eau fournit souvent le point de départ : sable accumulé, talus, végétation ou passage aménagé.', 'Le sable se déplace sous l’action du vent, des vagues et des courants. Une plage peut ainsi changer de profil selon les conditions et les saisons. Dans les dunes, la végétation aide à retenir le sable ; les passages répétés peuvent l’abîmer et faciliter son déplacement. Le chemin emprunté par notre groupe fait donc partie du sujet.', 'Ce sable n’est pas forcément resté ici depuis notre dernière séance : qu’est-ce qui a pu le déplacer ?', 'Une accumulation de sable, un changement de pente, la végétation de dune et les passages aménagés.', 'La plage évolue ; nos passages peuvent respecter ou fragiliser les éléments qui retiennent le sable.', 'Le sable serait un sol stable, et marcher dans la dune n’aurait pas de conséquence.', '[{"id":"directrice-plage-dunes-passage","label":"Raconter notre passage","consigne":"Sur le chemin habituel, faites repérer un signe de déplacement du sable. Reliez-le au vent ou aux vagues, puis demandez pourquoi le groupe emprunte le passage aménagé plutôt qu’un raccourci dans la végétation.","confirmation":"Nous avons parlé du déplacement du sable et de notre passage sur le site."}]'::jsonb, 'PROTÉGER', 1, array['caracteristiques_littoral']::text[], array['plage','dune','dunes','sable','érosion']::text[], 'La végétation des dunes contribue à retenir le sable.', 'Passer dans la végétation des dunes ne change rien, puisque le sable bouge déjà naturellement.', 'copun', true),
('directrice-laisse-mer', 'Qu’est-ce que la mer a laissé sur la plage ?', 'Distinguer les dépôts naturels des déchets et donner du sens à une observation ou à un ramassage.', 'Une algue, une coquille ou un déchet rencontré au retour suffit. Inutile de prévoir un inventaire ou un nettoyage complet.', 'La laisse de mer rassemble ce que la mer dépose près de sa limite de montée : algues, bois, coquilles, parfois aussi des déchets. Les éléments naturels servent de nourriture et d’abri à de petits animaux et contribuent au fonctionnement du rivage. Une plage vivante n’est donc pas forcément une plage sans dépôts.', 'Dans ce que la mer a déposé, qu’est-ce qui appartient au milieu et qu’est-ce qui vient de nos déchets ?', 'Des éléments naturels et des déchets dans une même zone de dépôt, sans manipuler d’objets coupants ou inconnus.', 'Retirer les déchets ne signifie pas retirer toute la laisse de mer.', 'Une plage propre devrait être débarrassée de toutes ses algues et de tous ses dépôts.', '[{"id":"directrice-laisse-mer-distinguer","label":"Garder ce qui fait vivre la plage","consigne":"Choisissez deux éléments visibles : un dépôt naturel et un déchet. Faites expliquer leur différence, puis cherchez ce qu’un animal peut trouver dans les dépôts naturels. Si un ramassage est adapté, ciblez les déchets identifiables.","confirmation":"Nous avons distingué des dépôts naturels des déchets présents sur la plage."}]'::jsonb, 'PROTÉGER', 1, array['caracteristiques_littoral']::text[], array['laisse de mer','algue','algues','déchet','déchets','plastique','traces']::text[], 'Les algues déposées sur la plage peuvent servir de nourriture et d’abri à des animaux.', 'Pour préserver la plage, il faut retirer tous les dépôts naturels laissés par la mer.', 'copun', true),
('directrice-vivant', 'Qui vit ici, même quand on ne le voit pas ?', 'Ouvrir une discussion sur le vivant à partir d’une présence ou d’une trace, sans exiger de connaître les espèces.', 'Vous pouvez dire « je ne sais pas encore ce que c’est ». Décrire ce qui est visible permet déjà de faire observer et de poser une question juste.', 'Le littoral offre des lieux pour se nourrir, s’abriter et se reproduire. Certaines présences sont visibles, d’autres se remarquent par une trace ou changent avec la marée et la saison. Observer un comportement ou un lien avec le lieu est déjà utile, même sans identifier l’espèce. Garder ses distances aide à voir ce que l’animal fait naturellement.', 'On ne connaît peut-être pas son nom. Mais qu’est-ce qui nous montre qu’un animal utilise cet endroit ?', 'Une présence, une coquille, une trace dans le sable, un déplacement ou un comportement observé pendant la séance.', 'On peut découvrir le vivant en observant ce qu’il fait et ce que le lieu lui offre, avant de chercher son nom.', 'Sans pouvoir nommer une espèce, on ne pourrait rien dire d’intéressant à son sujet.', '[{"id":"directrice-vivant-decrire","label":"Décrire avant de nommer","consigne":"À partir d’une présence ou d’une trace rencontrée, demandez au groupe de décrire ce qu’il voit. Cherchez ensuite ce que ce lieu peut offrir à un animal. Gardez une question à vérifier plutôt que d’inventer une identification.","confirmation":"Nous avons observé une présence ou une trace du vivant et parlé de son lien avec le lieu."}]'::jsonb, 'OBSERVER', 1, array['biodiversite_saisonnalite']::text[], array['vivant','animal','poisson','méduse','méduses','phoque','coquille','espèce']::text[], 'Décrire une trace ou un comportement permet de découvrir le vivant même sans connaître le nom d’une espèce.', 'Pour observer un animal avec le groupe, il faut d’abord pouvoir donner son nom exact.', 'copun', true),
('directrice-oiseaux', 'Pourquoi les oiseaux sont-ils ici, à ce moment-là ?', 'Relier un comportement d’oiseaux aux ressources et aux rythmes du littoral.', 'Une halte ou un retour au bord convient. Commencez par leur comportement plutôt que par une liste de noms.', 'Les oiseaux utilisent le littoral pour se nourrir, se reposer ou faire une halte pendant leurs déplacements. Selon la marée, les zones de nourriture disponibles et les lieux de repos changent. La saison compte aussi : on ne voit pas forcément les mêmes oiseaux toute l’année. Les faire s’envoler interrompt l’activité qu’ils étaient venus mener.', 'Ils sont regroupés ici : sont-ils en train de manger, de se reposer ou de se déplacer ?', 'L’endroit où les oiseaux se tiennent et ce qu’ils font : chercher dans la vase, nager, se poser ou rester immobiles.', 'Un lieu sert à des activités précises du vivant ; notre distance permet de les observer sans les interrompre.', 'Faire envoler un groupe d’oiseaux serait une manière de mieux les voir sans les gêner.', '[{"id":"directrice-oiseaux-comportement","label":"Comprendre leur halte","consigne":"À distance, faites décrire l’activité des oiseaux. Demandez ce que cet endroit leur offre maintenant et ce qui pourrait changer avec la marée. Choisissez un passage qui leur permet de poursuivre cette activité.","confirmation":"Nous avons relié le comportement des oiseaux à leur lieu et adapté notre passage."}]'::jsonb, 'OBSERVER', 1, array['biodiversite_saisonnalite']::text[], array['oiseau','oiseaux','migration','repos','vasière']::text[], 'La marée peut changer les endroits où les oiseaux trouvent de la nourriture ou se reposent.', 'Un oiseau qui s’envole à notre approche a forcément terminé ce qu’il faisait.', 'copun', true),
('directrice-lieu', 'Qu’est-ce qui rend cet endroit différent du secteur voisin ?', 'Faire lire le lieu d’évolution en reliant ses caractéristiques à la pratique et au vivant.', 'Profitez d’un changement de zone ou d’une pause prévue. Comparez deux lieux connus du groupe, sans chercher à tout expliquer.', 'Une côte ouverte, une baie abritée, une plage de sable ou une zone rocheuse n’offrent pas les mêmes conditions. L’exposition, le fond et les accès influencent notre pratique et les possibilités de vie. Comparer deux secteurs aide à comprendre le lieu à partir de différences concrètes plutôt qu’à accumuler des informations générales.', 'Qu’est-ce que cet endroit offre que le secteur voisin n’offre pas ?', 'Une différence d’exposition, de relief, de fond visible, d’accès ou de présence du vivant entre deux secteurs.', 'Les caractéristiques d’un lieu expliquent une partie de ce que nous pouvons y faire et de ce qui peut y vivre.', 'Deux secteurs voisins du littoral offriraient les mêmes conditions de pratique et de vie.', '[{"id":"directrice-lieu-comparer","label":"Comparer deux secteurs","consigne":"Lors d’une pause ou d’un changement de zone, faites nommer une différence avec le secteur précédent. Cherchez une conséquence pour notre séance et une possibilité pour le vivant : abri, nourriture ou zone de repos.","confirmation":"Nous avons relié une caractéristique du lieu à notre pratique ou au vivant."}]'::jsonb, 'OBSERVER', 1, array['lecture_paysage']::text[], array['lieu','paysage','baie','rochers','repère','abri','territoire']::text[], 'Deux secteurs proches peuvent offrir des conditions différentes selon leur exposition et leur relief.', 'Deux plages voisines accueillent forcément le même vivant et les mêmes conditions de pratique.', 'copun', true),
('directrice-littoral-partage', 'Avec qui partageons-nous ce morceau de littoral ?', 'Relier les usages du site à des choix concrets de pratique et de respect du milieu.', 'Un bateau de pêche, un aménagement ou un changement de passage donne une occasion d’en parler. Appuyez-vous sur un choix réel de la séance.', 'Le littoral est à la fois un lieu de travail, de loisirs et de vie pour de nombreuses espèces. Nos activités s’y croisent avec celles d’autres usagers et avec des besoins du vivant. Comprendre à quoi sert une zone ou un aménagement aide à expliquer nos choix : passage, distance, rangement du matériel ou gestion des déchets.', 'Pour nous, c’est un lieu de séance. Pour qui est-ce aussi un lieu de travail, de repos ou de nourriture ?', 'Une activité, un aménagement ou une zone utilisée par le vivant : accès portuaire, passage, lieu de pêche ou reposoir.', 'Partager le littoral commence par comprendre les usages et ajuster quelques gestes de notre pratique.', 'Un espace disponible pour notre groupe serait forcément sans usage ni besoin pour les autres.', '[{"id":"directrice-littoral-partage-choix","label":"Expliquer un choix de séance","consigne":"À partir d’un usage visible, demandez à qui le lieu sert. Expliquez un choix concret du groupe qui tient compte de cet usage ou du vivant, puis faites proposer un geste simple à conserver pendant la séance.","confirmation":"Nous avons parlé du partage du littoral à partir d’un choix de notre pratique."}]'::jsonb, 'PROTÉGER', 1, array['activites_humaines']::text[], array['usages','littoral','pêche','port','protection','impact','partage']::text[], 'Choisir notre passage et notre distance peut aider à partager le lieu avec ses autres usagers et le vivant.', 'Quand un espace paraît vide, notre pratique ne peut gêner aucun usage ni aucun animal.', 'copun', true)
